    // Event handler for when a new article is created via EditorActions
    private void OnArticleCreated(Common.Shared.ArticleLine article)
    {
        try
        {
            // Select the new article in the ViewModel on UI thread
            Avalonia.Threading.Dispatcher.UIThread.Post(() =>
            {
                try
                {
                    var vm = this.DataContext as IndexEditor.Views.EditorStateViewModel;
                    if (vm != null)
                    {
                        // Find the article in the VM's collection (it should match by reference or pages)
                        var inList = vm.Articles.FirstOrDefault(a => object.ReferenceEquals(a, article))
                                  ?? vm.Articles.FirstOrDefault(a => a.Pages != null && article.Pages != null && a.Pages.SequenceEqual(article.Pages));
                        var toSelect = inList ?? article;

                        // Select the article
                        if (vm.SelectArticleCommand != null && vm.SelectArticleCommand.CanExecute(toSelect))
                            vm.SelectArticleCommand.Execute(toSelect);
                        vm.SelectedArticle = toSelect;

                        DebugLogger.Log($"MainWindow.OnArticleCreated: Selected article in ViewModel");

                        // Focus the title field so user can start typing immediately
                        try
                        {
                            IndexEditor.Shared.EditorActions.FocusArticleTitle();
                            DebugLogger.Log($"MainWindow.OnArticleCreated: Requested focus on title field");
                        }
                        catch (Exception ex) { DebugLogger.LogException("MainWindow.OnArticleCreated: focus title", ex); }
                    }
                }
                catch (Exception ex) { DebugLogger.LogException("MainWindow.OnArticleCreated: select article in VM", ex); }
            }, Avalonia.Threading.DispatcherPriority.Background);
        }
        catch (Exception ex) { DebugLogger.LogException("MainWindow.OnArticleCreated: outer", ex); }
    }

    private void OnWindowOpened(object? sender, EventArgs e)
    {
        _windowLifecycleService?.OnWindowOpened();
    }

    private async void OnWindowClosing(object? sender, WindowClosingEventArgs e)
    {
        if (_windowLifecycleService == null) return;

        // Cancel the close temporarily to allow async processing
        e.Cancel = true;

        try
        {
            // Let the service handle the closing logic
            bool canClose = await _windowLifecycleService.OnWindowClosingAsync();

            if (canClose)
            {
                // Actually close the window (this time without canceling)
                this.Closing -= OnWindowClosing; // Unsubscribe to prevent recursion
                this.Close();
            }
        }
        catch (Exception ex)
        {
            DebugLogger.LogException("MainWindow.OnWindowClosing", ex);
            // Close anyway on error
            this.Closing -= OnWindowClosing;
            this.Close();
        }
    }

    private List<int> ParsePageNumbers(string pageStr, out bool hasError)
    {
        var pages = new List<int>();
        hasError = false;
        if (string.IsNullOrWhiteSpace(pageStr))
        {
            hasError = true;
            return pages;
        }

        var parts = pageStr.Split('|');
        foreach (var part in parts)
        {
            var trimmed = part.Trim();
            if (string.IsNullOrEmpty(trimmed))
            {
                hasError = true;
                continue;
            }
            if (trimmed.Contains('-'))
            {
                var range = trimmed.Split('-');
                if (range.Length == 2 && int.TryParse(range[0], out int start) && int.TryParse(range[1], out int end) && start <= end)
                {
                    for (int i = start; i <= end; i++)
                        pages.Add(i);
                }
                else
                {
                    hasError = true;
                }
            }
            else if (int.TryParse(trimmed, out int page))
            {
                pages.Add(page);
            }
            else
            {
                hasError = true;
            }
        }
        pages = pages.Distinct().OrderBy(p => p).ToList();
        return pages;
    }

    private bool ImageExistsInFolder(string folder, int pageNumber)
    {
        // Use FileOperationsService if available
        if (_fileOperationsService != null)
        {
            return _fileOperationsService.ImageExists(folder, pageNumber);
        }

        // Fallback: Use ImageHelper.ImageExists to check all possible filename patterns
        return IndexEditor.Shared.ImageHelper.ImageExists(folder, pageNumber);
    }

    // Main window event handlers
    // Main window keyboard event handler - delegates to specialized handlers
    private void OnMainWindowKeyDown(object? sender, KeyEventArgs e)
    {
        try
        {
            // Special handling for overlays that capture all input
            if (HandleOverlayKeyboard(e))
            {
                return;
            }

            // Dispatch to keyboard handlers
            if (_keyboardDispatcher != null)
            {
                try
                {
                    if (_keyboardDispatcher.Dispatch(e))
                    {
                        return; // Handler processed the event
                    }
                }
                catch (Exception ex)
                {
                    DebugLogger.LogException("MainWindow: keyboard dispatcher", ex);
                }
            }

            // Handle F1 for help overlay (not in handlers to avoid dependency on overlay)
            if (e.Key == Key.F1)
            {
                _overlayManager?.ToggleHelpOverlay();
                e.Handled = true;
            }

            // Handle Delete key for article deletion
            if (e.Key == Key.Delete && !e.KeyModifiers.HasFlag(KeyModifiers.Control) && !e.KeyModifiers.HasFlag(KeyModifiers.Alt))
            {
                HandleDeleteKey(e);
            }
        }
        catch (Exception ex)
        {
            DebugLogger.LogException("MainWindow: OnMainWindowKeyDown", ex);
        }
    }

    // Handle keyboard input when overlays are visible
    private bool HandleOverlayKeyboard(KeyEventArgs e)
    {
        try
        {
            // Fullscreen image overlay: Esc to close (highest priority)
            if (_fullscreenService?.IsFullscreenVisible() ?? false)
            {
                if (e.Key == Key.Escape)
                {
                    CloseFullscreenImage();
                    e.Handled = true;
                    return true;
                }
                // Block other shortcuts while fullscreen is visible
                return true;
            }

            var overlay = this.FindControl<Border>("IndexOverlay");

            // Index overlay: capture Ctrl+I and Esc to close
            if (overlay != null && overlay.IsVisible)
            {

                // Ctrl+I: Toggle overlay
                if (e.Key == Key.I && (e.KeyModifiers.HasFlag(KeyModifiers.Control) || e.KeyModifiers.HasFlag(KeyModifiers.Meta)))
                {
                    _overlayManager?.CloseIndexOverlay();
                    e.Handled = true;
                    return true;
                }

                // Esc: Close overlay
                if (e.Key == Key.Escape)
                {
                    _overlayManager?.CloseIndexOverlay();
                    e.Handled = true;
                    return true;
                }

                // Ctrl+S: Save overlay content (handled by FileKeyboardHandler but needs early return)
                if (e.Key == Key.S && e.KeyModifiers.HasFlag(KeyModifiers.Control))
                {
                    // Let the FileKeyboardHandler handle this
                    return false;
                }

                // All other keys go to the textbox
                return true;
            }

            // Help overlay: Esc or F1 to close
            if (_overlayManager?.IsHelpOverlayVisible() ?? false)
            {
                if (e.Key == Key.Escape || e.Key == Key.F1)
                {
                    _overlayManager?.CloseHelpOverlay();
                    e.Handled = true;
                    return true;
                }
                return true; // Block other shortcuts while help is visible
            }

            // Delete confirmation overlay: Enter to confirm, Esc to cancel
            if (_overlayManager?.IsDeleteConfirmationVisible() ?? false)
            {
                if (e.Key == Key.Enter || e.Key == Key.Y)
                {
                    try { DeleteSelectedArticleAndCloseOverlay(); }
                    catch (Exception ex) { DebugLogger.LogException("MainWindow: confirm delete", ex); }
                    e.Handled = true;
                    return true;
                }
                if (e.Key == Key.Escape || e.Key == Key.N)
                {
                    _overlayManager?.CloseDeleteConfirmation();
                    e.Handled = true;
                    return true;
                }
                return true; // Block other shortcuts while delete confirmation is visible
            }
        }
        catch (Exception ex)
        {
            DebugLogger.LogException("MainWindow: HandleOverlayKeyboard", ex);
        }

        return false;
    }

    // Handle Delete key for article deletion
    private void HandleDeleteKey(KeyEventArgs e)
    {
        try
        {
            if (_articleDeletionService == null) return;

            if (!_articleDeletionService.CanDeleteArticle())
            {
                // Check if we should show a message about active segment
                var activeSeg = IndexEditor.Shared.EditorState.ActiveSegment;
                if (activeSeg != null && activeSeg.IsActive)
                {
                    IndexEditor.Shared.ToastService.Show("End or cancel the active segment before deleting an article");
                    e.Handled = true;
                }
                return;
            }

            // Get the article to show in the confirmation dialog
            var vm = this.DataContext as IndexEditor.Views.EditorStateViewModel;
            var article = vm?.SelectedArticle ?? IndexEditor.Shared.EditorState.ActiveArticle;

            if (article != null)
            {
                _articleDeletionService.ShowDeleteConfirmation(article);
                e.Handled = true;
            }
        }
        catch (Exception ex)
        {
            DebugLogger.LogException("MainWindow: HandleDeleteKey", ex);
        }
    }
    private async void OnOpenButtonClick(object sender, RoutedEventArgs e)
    {
        // Open folder using FolderBrowserWindow.ShowDialogAsync and update EditorState on UI thread
        try
        {
            var wnd = this.VisualRoot as Window ?? this;
            var start = IndexEditor.Shared.EditorState.CurrentFolder;
            string? path = null;
            try
            {
                path = await IndexEditor.Shared.FolderPicker.PickFolderAsync(wnd, start);
            }
            catch (Exception ex) { DebugLogger.LogException("MainWindow: folder picker", ex); }
            if (!string.IsNullOrWhiteSpace(path))
            {
                Avalonia.Threading.Dispatcher.UIThread.Post(() =>
                {
                    IndexEditor.Shared.EditorState.CurrentFolder = path;
                    LoadArticlesFromFolder(path);
                });
            }
        }
        catch (Exception ex) { DebugLogger.LogException("MainWindow: OnOpenButtonClick", ex); }
    }

    // Show fullscreen image overlay
    private void ShowFullscreenImage(Avalonia.Media.IImage imageSource, int pageNumber)
    {
        _fullscreenService?.ShowFullscreen(imageSource, pageNumber);
    }

    // Close fullscreen image overlay
    private void CloseFullscreenImage()
    {
        _fullscreenService?.CloseFullscreen();
    }

    private void LoadArticlesFromFolder(string folder)
    {
        _folderLoadingService?.LoadFolder(folder);
    }

    // Helper: delete currently selected article (VM selected or EditorState active) and close delete overlay
    private void DeleteSelectedArticleAndCloseOverlay()
    {
        _articleDeletionService?.DeleteSelectedArticle();
    }
}

using System;
using System.Net.Http;
using System.Threading.Tasks;
using System.Linq;
using IndexEditor.Shared;

namespace IndexEditor.Services;

/// <summary>
/// Service to check if a model has a page on babepedia.com
/// </summary>
public class BabepediaService
{
    private static readonly HttpClient _httpClient = new HttpClient();

    static BabepediaService()
    {
        _httpClient.Timeout = TimeSpan.FromSeconds(5);
        _httpClient.DefaultRequestHeaders.Add("User-Agent", "Mozilla/5.0 (compatible; IndexEditor/1.0)");
    }

    /// <summary>
    /// Checks if a model has a page on babepedia.com
    /// </summary>
    /// <param name="modelName">The model name to search for</param>
    /// <returns>True if a page exists, false otherwise</returns>
    public static async Task<(bool exists, string url)> CheckModelPageAsync(string modelName)
    {
        try
        {
            if (string.IsNullOrWhiteSpace(modelName))
            {
                return (false, string.Empty);
            }

            // Clean up the model name for URL
            // Replace spaces with underscores, remove special characters
            var cleanName = modelName.Trim()
                .Replace(" ", "_")
                .Replace("'", "")
                .Replace("\"", "");

            // Babepedia URL format: https://www.babepedia.com/babe/Model_Name
            var requestedUrl = $"https://www.babepedia.com/babe/{Uri.EscapeDataString(cleanName)}";

            DebugLogger.Log($"BabepediaService: Checking URL: {requestedUrl}");

            var response = await _httpClient.GetAsync(requestedUrl);

            // Babepedia redirects from /babe/Name to /search/Name when the model doesn't exist
            // We need to check if the final URL after redirects is different from what we requested
            var finalUrl = response.RequestMessage?.RequestUri?.ToString() ?? requestedUrl;

            DebugLogger.Log($"BabepediaService: Requested: {requestedUrl}");
            DebugLogger.Log($"BabepediaService: Final URL: {finalUrl}");

            // Check if we got redirected to a search page
            bool wasRedirectedToSearch = finalUrl.Contains("/search/", StringComparison.OrdinalIgnoreCase);

            // The page exists only if:
            // 1. The request was successful (200 OK)
            // 2. We were NOT redirected to a search page
            bool exists = response.IsSuccessStatusCode && !wasRedirectedToSearch;

            DebugLogger.Log($"BabepediaService: {modelName} -> Status: {response.StatusCode}, Redirected to search: {wasRedirectedToSearch}, Exists: {exists}");

            return (exists, exists ? finalUrl : string.Empty);
        }
        catch (TaskCanceledException)
        {
            DebugLogger.Log($"BabepediaService: Timeout checking {modelName}");
            return (false, string.Empty);
        }
        catch (Exception ex)
        {
            DebugLogger.LogException($"BabepediaService: Error checking {modelName}", ex);
            return (false, string.Empty);
        }
    }

    /// <summary>
    /// Checks babepedia for the first model name in an article
    /// </summary>
    public static async Task<(bool exists, string modelName, string url)> CheckArticleModelAsync(Common.Shared.ArticleLine article)
    {
        try
        {
            if (article == null)
            {
                return (false, string.Empty, string.Empty);
            }

            // Only check Model and Cover categories
            if (article.Category != "Model" && article.Category != "Cover")
            {
                return (false, string.Empty, string.Empty);
            }

            // Get the first model name
            var modelName = article.ModelNames?.FirstOrDefault();
            if (string.IsNullOrWhiteSpace(modelName))
            {
                return (false, string.Empty, string.Empty);
            }

            var (exists, url) = await CheckModelPageAsync(modelName);
            return (exists, modelName ?? string.Empty, url);
        }
        catch (Exception ex)
        {
            DebugLogger.LogException("BabepediaService: CheckArticleModelAsync", ex);
            return (false, string.Empty, string.Empty);
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Common.Shared;
using Microsoft.Extensions.Logging;

namespace IndexEditor.Services;

/// <summary>
/// Implementation of IIndexFileService for loading and saving index files.
/// Consolidates duplicate loading logic from MainWindow and ArticleEditorView.
/// </summary>
public class IndexFileService : IIndexFileService
{
    private readonly ILogger<IndexFileService> _logger;

    public IndexFileService(ILogger<IndexFileService> logger)
    {
        _logger = logger;
    }

    public (string Magazine, string Volume, string Number, string Year, List<ArticleLine> Articles, List<MagazineLink> Links) LoadFromFolder(string folderPath)
    {
        if (string.IsNullOrWhiteSpace(folderPath))
        {
            throw new ArgumentException("Folder path cannot be null or empty", nameof(folderPath));
        }

        // Normalize path
        var normalizedPath = Path.GetFullPath(folderPath);

        if (!Directory.Exists(normalizedPath))
        {
            throw new DirectoryNotFoundException($"Folder not found: {normalizedPath}");
        }

        _logger.LogInformation("LoadFromFolder: Input folder: '{Folder}'", folderPath);
        _logger.LogInformation("LoadFromFolder: Normalized '{Original}' to '{Normalized}'", folderPath, normalizedPath);

        // Determine which index file exists
        var jsonIndexPath = Path.Combine(normalizedPath, "_index.json");
        var txtIndexPath = Path.Combine(normalizedPath, "_index.txt");

        if (File.Exists(jsonIndexPath))
        {
            return LoadFromJsonFile(jsonIndexPath, normalizedPath);
        }
        else if (File.Exists(txtIndexPath))
        {
            return LoadFromTxtFile(txtIndexPath, normalizedPath);
        }
        else
        {
            throw new FileNotFoundException($"No index file found in folder: {normalizedPath}");
        }
    }

    public void SaveToFolder(string folderPath, string magazine, string volume, string number, string year,
        List<ArticleLine> articles, List<MagazineLink> links)
    {
        if (string.IsNullOrWhiteSpace(folderPath))
        {
            throw new ArgumentException("Folder path cannot be null or empty", nameof(folderPath));
        }

        var normalizedPath = Path.GetFullPath(folderPath);

        if (!Directory.Exists(normalizedPath))
        {
            throw new DirectoryNotFoundException($"Folder not found: {normalizedPath}");
        }

        // Always save as JSON
        var jsonIndexPath = Path.Combine(normalizedPath, "_index.json");

        _logger.LogInformation("SaveToFolder: Saving to '{Path}'", jsonIndexPath);

        // Create backup first
        BackupIndexFile(normalizedPath);

        // Save using IndexJsonSerializer
        Common.Shared.IndexJsonSerializer.SaveToJson(normalizedPath, magazine, volume, number, year, articles, links);

        _logger.LogInformation("SaveToFolder: Successfully saved index file");
    }

    public bool HasJsonIndex(string folderPath)
    {
        if (string.IsNullOrWhiteSpace(folderPath))
        {
            return false;
        }

        var normalizedPath = Path.GetFullPath(folderPath);
        var jsonIndexPath = Path.Combine(normalizedPath, "_index.json");

        return File.Exists(jsonIndexPath);
    }

    public void BackupIndexFile(string folderPath)
    {
        if (string.IsNullOrWhiteSpace(folderPath))
        {
            return;
        }

        var normalizedPath = Path.GetFullPath(folderPath);
        var indexPath = Path.Combine(normalizedPath, "_index.json");

        if (!File.Exists(indexPath))
        {
            // Try TXT format
            indexPath = Path.Combine(normalizedPath, "_index.txt");
        }

        if (File.Exists(indexPath))
        {
            var backupPath = indexPath + "~";

            try
            {
                File.Copy(indexPath, backupPath, overwrite: true);
                _logger.LogInformation("BackupIndexFile: Created backup at '{BackupPath}'", backupPath);
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "BackupIndexFile: Failed to create backup");
            }
        }
    }

    private (string, string, string, string, List<ArticleLine>, List<MagazineLink>) LoadFromJsonFile(string jsonPath, string folderPath)
    {
        _logger.LogInformation("LoadFromFolder: Loading from _index.json");

        var (magazine, volume, number, year, articles, links) = Common.Shared.IndexJsonSerializer.LoadFromJson(folderPath);

        // Deduplicate links
        var linksList = links ?? new List<MagazineLink>();
        var uniqueLinks = linksList
            .GroupBy(link => $"{link.Page}|{link.Magazine}|{link.Volume}|{link.Issue}")
            .Select(g => g.First())
            .ToList();

        if (uniqueLinks.Count != linksList.Count)
        {
            _logger.LogInformation("Loaded {Original} unique links from JSON (deduplicated from {Total})", 
                uniqueLinks.Count, linksList.Count);
        }

        return (magazine, volume, number, year, articles, uniqueLinks);
    }

    private (string, string, string, string, List<ArticleLine>, List<MagazineLink>) LoadFromTxtFile(string txtPath, string folderPath)
    {
        _logger.LogInformation("LoadFromFolder: Loading from _index.txt");

        var lines = File.ReadAllLines(txtPath);
        var articles = new List<ArticleLine>();
        string magazine = "";
        string volume = "—";
        string number = "—";
        string year = "—";

        // Parse header for metadata (volume, issue, etc.)
        if (lines.Length > 0 && lines[0].StartsWith("#"))
        {
            // Parse metadata from first line: # Magazine Name Vol X No Y
            var headerParts = lines[0].TrimStart('#').Trim().Split(new[] { "Vol", "No" }, StringSplitOptions.None);
            if (headerParts.Length >= 3)
            {
                magazine = headerParts[0].Trim();
                volume = headerParts[1].Trim();
                number = headerParts[2].Trim();
            }
        }

        // Parse articles
        foreach (var line in lines)
        {
            if (string.IsNullOrWhiteSpace(line) || line.StartsWith("#"))
            {
                continue;
            }

            try
            {
                var article = IndexEditor.Shared.IndexFileParser.ParseArticleLine(line);
                if (article != null)
                {
                    articles.Add(article);
                }
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "Failed to parse line: {Line}", line);
            }
        }

        _logger.LogInformation("LoadFromFolder: Loaded {Count} articles from TXT file", articles.Count);

        // TXT files don't have links
        return (magazine, volume, number, year, articles, new List<MagazineLink>());
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Common.Shared;
using Microsoft.Extensions.Logging;

namespace IndexEditor.Services;

/// <summary>
/// Implementation of IIndexFileService for loading and saving index files.
/// Consolidates duplicate loading logic from MainWindow and ArticleEditorView.
/// </summary>
public class IndexFileService : IIndexFileService
{
    private readonly ILogger<IndexFileService> _logger;

    public IndexFileService(ILogger<IndexFileService> logger)
    {
        _logger = logger;
    }

    public (string Magazine, string Volume, string Number, string Year, List<ArticleLine> Articles, List<MagazineLink> Links) LoadFromFolder(string folderPath)
    {
        if (string.IsNullOrWhiteSpace(folderPath))
        {
            throw new ArgumentException("Folder path cannot be null or empty", nameof(folderPath));
        }

        // Normalize path
        var normalizedPath = Path.GetFullPath(folderPath);

        if (!Directory.Exists(normalizedPath))
        {
            throw new DirectoryNotFoundException($"Folder not found: {normalizedPath}");
        }

        _logger.LogInformation("LoadFromFolder: Input folder: '{Folder}'", folderPath);
        _logger.LogInformation("LoadFromFolder: Normalized '{Original}' to '{Normalized}'", folderPath, normalizedPath);

        // Determine which index file exists
        var jsonIndexPath = Path.Combine(normalizedPath, "_index.json");
        var txtIndexPath = Path.Combine(normalizedPath, "_index.txt");

        if (File.Exists(jsonIndexPath))
        {
            return LoadFromJsonFile(jsonIndexPath, normalizedPath);
        }
        else if (File.Exists(txtIndexPath))
        {
            return LoadFromTxtFile(txtIndexPath, normalizedPath);
        }
        else
        {
            // No index file exists - parse metadata from folder name
            _logger.LogInformation("LoadFromFolder: No index file found, parsing folder name for metadata");

            var folderName = Path.GetFileName(normalizedPath);
            var (magazine, volume, number, year) = IndexEditor.Shared.FolderMetadataParser.ParseFolderMetadata(folderName);

            _logger.LogInformation("LoadFromFolder: Parsed metadata - Magazine: '{Magazine}', Vol: '{Volume}', Num: '{Number}', Year: '{Year}'",
                magazine, volume, number, year);

            // Return empty article and link lists with parsed metadata
            return (magazine, volume, number, year, new List<ArticleLine>(), new List<MagazineLink>());
        }
    }

    public void SaveToFolder(string folderPath, string magazine, string volume, string number, string year,
        List<ArticleLine> articles, List<MagazineLink> links)
    {
        if (string.IsNullOrWhiteSpace(folderPath))
        {
            throw new ArgumentException("Folder path cannot be null or empty", nameof(folderPath));
        }

        var normalizedPath = Path.GetFullPath(folderPath);

        if (!Directory.Exists(normalizedPath))
        {
            throw new DirectoryNotFoundException($"Folder not found: {normalizedPath}");
        }

        // Always save as JSON
        var jsonIndexPath = Path.Combine(normalizedPath, "_index.json");

        _logger.LogInformation("SaveToFolder: Saving to '{Path}'", jsonIndexPath);

        // Create backup first
        BackupIndexFile(normalizedPath);

        // Save using IndexJsonSerializer
        Common.Shared.IndexJsonSerializer.SaveToJson(normalizedPath, magazine, volume, number, year, articles, links);

        _logger.LogInformation("SaveToFolder: Successfully saved index file");
    }

    public bool HasJsonIndex(string folderPath)
    {
        if (string.IsNullOrWhiteSpace(folderPath))
        {
            return false;
        }

        var normalizedPath = Path.GetFullPath(folderPath);
        var jsonIndexPath = Path.Combine(normalizedPath, "_index.json");

        return File.Exists(jsonIndexPath);
    }

    public void BackupIndexFile(string folderPath)
    {
        if (string.IsNullOrWhiteSpace(folderPath))
        {
            return;
        }

        var normalizedPath = Path.GetFullPath(folderPath);
        var indexPath = Path.Combine(normalizedPath, "_index.json");

        if (!File.Exists(indexPath))
        {
            // Try TXT format
            indexPath = Path.Combine(normalizedPath, "_index.txt");
        }

        if (File.Exists(indexPath))
        {
            var backupPath = indexPath + "~";

            try
            {
                File.Copy(indexPath, backupPath, overwrite: true);
                _logger.LogInformation("BackupIndexFile: Created backup at '{BackupPath}'", backupPath);
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "BackupIndexFile: Failed to create backup");
            }
        }
    }

    private (string, string, string, string, List<ArticleLine>, List<MagazineLink>) LoadFromJsonFile(string jsonPath, string folderPath)
    {
        _logger.LogInformation("LoadFromFolder: Loading from _index.json");

        var (magazine, volume, number, year, articles, links) = Common.Shared.IndexJsonSerializer.LoadFromJson(folderPath);

        // Deduplicate links
        var linksList = links ?? new List<MagazineLink>();
        var uniqueLinks = linksList
            .GroupBy(link => $"{link.Page}|{link.Magazine}|{link.Volume}|{link.Issue}")
            .Select(g => g.First())
            .ToList();

        if (uniqueLinks.Count != linksList.Count)
        {
            _logger.LogInformation("Loaded {Original} unique links from JSON (deduplicated from {Total})", 
                uniqueLinks.Count, linksList.Count);
        }

        return (magazine, volume, number, year, articles, uniqueLinks);
    }

    private (string, string, string, string, List<ArticleLine>, List<MagazineLink>) LoadFromTxtFile(string txtPath, string folderPath)
    {
        _logger.LogInformation("LoadFromFolder: Loading from _index.txt");

        var lines = File.ReadAllLines(txtPath);
        var articles = new List<ArticleLine>();
        string magazine = "";
        string volume = "—";
        string number = "—";
        string year = "—";

        int articleStartIndex = 0;

        // Parse metadata from first non-comment line (CSV format: Magazine,Volume,Number or Magazine,Volume,Number,Year)
        for (int i = 0; i < lines.Length; i++)
        {
            var line = lines[i].Trim();

            // Skip empty lines and comments
            if (string.IsNullOrWhiteSpace(line) || line.StartsWith("#"))
            {
                continue;
            }

            // First non-comment line: try CSV metadata
            var parts = IndexEditor.Shared.IndexFileParser.SplitRespectingEscapedCommas(line);
            if (parts.Count >= 3)
            {
                // Unescape comma escaping
                string Unescape(string s) => s.Replace("\\,", ",");

                magazine = Unescape(parts[0]);
                volume = Unescape(parts[1]);
                number = Unescape(parts[2]);

                // If 4th field exists, use it as year
                if (parts.Count >= 4 && !string.IsNullOrWhiteSpace(parts[3]))
                {
                    year = Unescape(parts[3]);
                }
                else
                {
                    // No year in file, try to parse from folder name
                    var folderName = Path.GetFileName(folderPath);
                    var (_, _, _, folderYear) = IndexEditor.Shared.FolderMetadataParser.ParseFolderMetadata(folderName);
                    year = folderYear;
                }

                _logger.LogInformation("LoadFromTxtFile: Parsed metadata - Magazine: '{Magazine}', Vol: '{Volume}', Num: '{Number}', Year: '{Year}'",
                    magazine, volume, number, year);

                articleStartIndex = i + 1;
                break;
            }

            // If first non-comment line doesn't have 3+ parts, it might be an article - don't skip it
            articleStartIndex = i;
            break;
        }

        // Parse articles starting after metadata line
        for (int i = articleStartIndex; i < lines.Length; i++)
        {
            var line = lines[i];

            if (string.IsNullOrWhiteSpace(line) || line.StartsWith("#"))
            {
                continue;
            }

            try
            {
                var article = IndexEditor.Shared.IndexFileParser.ParseArticleLine(line);
                if (article != null)
                {
                    articles.Add(article);
                }
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "Failed to parse line: {Line}", line);
            }
        }

        _logger.LogInformation("LoadFromFolder: Loaded {Count} articles from TXT file", articles.Count);

        // TXT files don't have links
        return (magazine, volume, number, year, articles, new List<MagazineLink>());
    }
}

using System;
using System.IO;
using Avalonia.Controls;
using Avalonia.Input;
using Avalonia.Threading;
using IndexEditor.Shared;
using IndexEditor.Views;

namespace IndexEditor.Services.KeyboardHandlers;

/// <summary>
/// Handles keyboard shortcuts related to file operations.
/// - Ctrl+O: Open folder
/// - Ctrl+S: Save index file
/// - Ctrl+I: Toggle index file overlay
/// - F11: Toggle fullscreen
/// </summary>
public class FileKeyboardHandler : IKeyboardShortcutHandler
{
    private readonly Window _window;
    private readonly Action<string>? _loadArticlesFromFolder;
    private readonly OverlayManager? _overlayManager;
    private readonly IEditorState _editorState;

    public FileKeyboardHandler(Window window, IEditorState editorState, Action<string>? loadArticlesFromFolder = null, OverlayManager? overlayManager = null)
    {
        _window = window ?? throw new ArgumentNullException(nameof(window));
        _editorState = editorState ?? throw new ArgumentNullException(nameof(editorState));
        _loadArticlesFromFolder = loadArticlesFromFolder;
        _overlayManager = overlayManager;
    }

    public int Priority => 80; // High priority for file operations

    public bool TryHandle(KeyEventArgs e)
    {
        // Ctrl+O: Open folder
        if (e.Key == Key.O && e.KeyModifiers.HasFlag(KeyModifiers.Control))
        {
            HandleCtrlO(e);
            return true;
        }

        // Ctrl+S: Save index file
        if (e.Key == Key.S && e.KeyModifiers.HasFlag(KeyModifiers.Control))
        {
            HandleCtrlS(e);
            return true;
        }

        // Ctrl+I: Toggle index file overlay
        if (e.Key == Key.I && e.KeyModifiers.HasFlag(KeyModifiers.Control))
        {
            HandleCtrlI(e);
            return true;
        }

        // F11: Toggle fullscreen
        if (e.Key == Key.F11)
        {
            HandleF11(e);
            return true;
        }

        return false;
    }

    private void HandleCtrlO(KeyEventArgs e)
    {
        try
        {
            var active = _editorState.ActiveSegment;
            if (active != null && active.IsActive)
            {
                ToastService.Show("End or cancel the active segment before opening a new folder");
                e.Handled = true;
                return;
            }

            var start = _editorState.CurrentFolder;

            // Dispatch an async folder picker
            Dispatcher.UIThread.Post(async () =>
            {
                try
                {
                    string? path = null;
                    try
                    {
                        path = await FolderPicker.PickFolderAsync(_window, start);
                    }
                    catch (Exception ex)
                    {
                        DebugLogger.LogException("FileKeyboardHandler: PickFolderAsync", ex);
                    }

                    if (!string.IsNullOrWhiteSpace(path))
                    {
                        _loadArticlesFromFolder?.Invoke(path);
                    }
                }
                catch (Exception ex)
                {
                    DebugLogger.LogException("FileKeyboardHandler: Ctrl+O async handler", ex);
                }
            });
        }
        catch (Exception ex)
        {
            DebugLogger.LogException("FileKeyboardHandler: Ctrl+O handler", ex);
        }

        e.Handled = true;
    }

    private void HandleCtrlS(KeyEventArgs e)
    {
        try
        {
            // Check if index overlay is visible - if so, save from there
            var overlay = _window.FindControl<Border>("IndexFileOverlay");
            if (overlay != null && overlay.IsVisible)
            {
                var textBox = _window.FindControl<TextBox>("IndexFileTextBox");
                if (textBox != null)
                {
                    try
                    {
                        var folder = _editorState.CurrentFolder;
                        if (string.IsNullOrWhiteSpace(folder))
                        {
                            ToastService.Show("No folder open; cannot save index");
                            e.Handled = true;
                            return;
                        }

                        var indexPath = Path.Combine(folder, "_index.txt");
                        File.WriteAllText(indexPath, textBox.Text ?? string.Empty);
                        ToastService.Show("Index saved");

                        // Close overlay and reload
                        overlay.IsVisible = false;
                        _loadArticlesFromFolder?.Invoke(folder);
                    }
                    catch (Exception ex)
                    {
                        ToastService.Show("Failed to save index");
                        DebugLogger.LogException("FileKeyboardHandler: Ctrl+S save from overlay", ex);
                    }
                }
                e.Handled = true;
                return;
            }

            // Normal save (overlay not visible)
            var active = _editorState.ActiveSegment;
            if (active != null && active.IsActive)
            {
                ToastService.Show("End or cancel the active segment before saving");
                e.Handled = true;
                return;
            }

            // Save the index file directly
            var saveFolder = _editorState.CurrentFolder;
            if (string.IsNullOrWhiteSpace(saveFolder))
            {
                ToastService.Show("No folder open; cannot save index");
                e.Handled = true;
                return;
            }

            try
            {
                var links = MainWindow.Instance?.GetDiscoveredLinks();
                IndexSaver.SaveIndex(saveFolder, links);
                ToastService.Show("Index saved");
            }
            catch (Exception saveEx)
            {
                ToastService.Show("Failed to save index");
                DebugLogger.LogException("FileKeyboardHandler: Save index", saveEx);
            }
        }
        catch (Exception ex)
        {
            DebugLogger.LogException("FileKeyboardHandler: Ctrl+S handler", ex);
        }

        e.Handled = true;
    }

    private void HandleCtrlI(KeyEventArgs e)
    {
        try
        {
            var folder = _editorState.CurrentFolder;
            if (string.IsNullOrWhiteSpace(folder))
            {
                ToastService.Show("No folder open");
                e.Handled = true;
                return;
            }

            // Use OverlayManager if available, otherwise fall back to direct control access
            if (_overlayManager != null)
            {
                _overlayManager.ToggleIndexOverlay(folder);
            }
            else
            {
                // Fallback to direct control access
                var overlay = _window.FindControl<Border>("IndexFileOverlay");
                if (overlay == null)
                {
                    e.Handled = true;
                    return;
                }

                if (!overlay.IsVisible)
                {
                    var indexPath = Path.Combine(folder, "_index.txt");
                    if (!File.Exists(indexPath))
                    {
                        ToastService.Show("_index.txt not found in current folder");
                        e.Handled = true;
                        return;
                    }

                    var textBox = _window.FindControl<TextBox>("IndexFileTextBox");
                    if (textBox != null)
                    {
                        try
                        {
                            textBox.Text = File.ReadAllText(indexPath);
                        }
                        catch (Exception ex)
                        {
                            DebugLogger.LogException("FileKeyboardHandler: Read _index.txt", ex);
                            textBox.Text = "(error reading file)";
                        }
                    }

                    overlay.IsVisible = true;
                }
                else
                {
                    overlay.IsVisible = false;
                }
            }
        }
        catch (Exception ex)
        {
            DebugLogger.LogException("FileKeyboardHandler: Ctrl+I handler", ex);
        }

        e.Handled = true;
    }

    private void HandleF11(KeyEventArgs e)
    {
        _window.WindowState = _window.WindowState == Avalonia.Controls.WindowState.FullScreen 
            ? Avalonia.Controls.WindowState.Normal 
            : Avalonia.Controls.WindowState.FullScreen;
        e.Handled = true;
    }
}

using System;
using System.IO;
using Avalonia.Controls;
using Avalonia.Input;
using Avalonia.Threading;
using IndexEditor.Shared;
using IndexEditor.Views;

namespace IndexEditor.Services.KeyboardHandlers;

/// <summary>
/// Handles keyboard shortcuts related to file operations.
/// - Ctrl+O: Open folder
/// - Ctrl+S: Save index file
/// - Ctrl+I: Toggle index file overlay
/// - F11: Toggle fullscreen
/// </summary>
public class FileKeyboardHandler : IKeyboardShortcutHandler
{
    private readonly Window _window;
    private readonly Action<string>? _loadArticlesFromFolder;
    private readonly OverlayManager? _overlayManager;
    private readonly IEditorState _editorState;
    private readonly LinkDiscoveryService? _linkDiscoveryService;

    public FileKeyboardHandler(
        Window window, 
        IEditorState editorState, 
        Action<string>? loadArticlesFromFolder = null, 
        OverlayManager? overlayManager = null,
        LinkDiscoveryService? linkDiscoveryService = null)
    {
        _window = window ?? throw new ArgumentNullException(nameof(window));
        _editorState = editorState ?? throw new ArgumentNullException(nameof(editorState));
        _loadArticlesFromFolder = loadArticlesFromFolder;
        _overlayManager = overlayManager;
        _linkDiscoveryService = linkDiscoveryService;
    }

    public int Priority => 80; // High priority for file operations

    public bool TryHandle(KeyEventArgs e)
    {
        // Ctrl+O: Open folder
        if (e.Key == Key.O && e.KeyModifiers.HasFlag(KeyModifiers.Control))
        {
            HandleCtrlO(e);
            return true;
        }

        // Ctrl+S: Save index file
        if (e.Key == Key.S && e.KeyModifiers.HasFlag(KeyModifiers.Control))
        {
            HandleCtrlS(e);
            return true;
        }

        // Ctrl+I: Toggle index file overlay
        if (e.Key == Key.I && e.KeyModifiers.HasFlag(KeyModifiers.Control))
        {
            HandleCtrlI(e);
            return true;
        }

        // Ctrl+B: Check babepedia for selected article
        if (e.Key == Key.B && e.KeyModifiers.HasFlag(KeyModifiers.Control))
        {
            HandleCtrlB(e);
            return true;
        }

        // F11: Toggle fullscreen
        if (e.Key == Key.F11)
        {
            HandleF11(e);
            return true;
        }

        return false;
    }

    private void HandleCtrlO(KeyEventArgs e)
    {
        try
        {
            var active = _editorState.ActiveSegment;
            if (active != null && active.IsActive)
            {
                ToastService.Show("End or cancel the active segment before opening a new folder");
                e.Handled = true;
                return;
            }

            // Check if link discovery scan is in progress
            if (_linkDiscoveryService?.IsScanning ?? false)
            {
                // Dispatch async dialog on UI thread
                Dispatcher.UIThread.Post(async () =>
                {
                    try
                    {
                        bool shouldWait = await ConfirmDialog.ShowDialog(
                            _window,
                            "A link discovery scan is currently in progress. Do you want to wait for it to complete before opening a new folder?");

                        if (!shouldWait)
                        {
                            // User chose to cancel scan and proceed
                            _linkDiscoveryService?.StopDiscovery();
                            ToastService.Show("Link discovery scan cancelled.");

                            // Now proceed with opening folder
                            await OpenFolderAsync();
                        }
                        else
                        {
                            ToastService.Show("Waiting for scan to complete. Try opening again when scan finishes.");
                        }
                    }
                    catch (Exception ex)
                    {
                        DebugLogger.LogException("FileKeyboardHandler: scan check dialog", ex);
                    }
                });
                e.Handled = true;
                return;
            }

            // No scan in progress, proceed with opening
            Dispatcher.UIThread.Post(async () => await OpenFolderAsync());
        }
        catch (Exception ex)
        {
            DebugLogger.LogException("FileKeyboardHandler: Ctrl+O handler", ex);
        }

        e.Handled = true;
    }

    private async System.Threading.Tasks.Task OpenFolderAsync()
    {
        try
        {
            var start = _editorState.CurrentFolder;
            string? path = null;
            try
            {
                path = await FolderPicker.PickFolderAsync(_window, start);
            }
            catch (Exception ex)
            {
                DebugLogger.LogException("FileKeyboardHandler: PickFolderAsync", ex);
            }

            if (!string.IsNullOrWhiteSpace(path))
            {
                _loadArticlesFromFolder?.Invoke(path);
            }
        }
        catch (Exception ex)
        {
            DebugLogger.LogException("FileKeyboardHandler: OpenFolderAsync", ex);
        }
    }

    private void HandleCtrlS(KeyEventArgs e)
    {
        try
        {
            // Check if index overlay is visible - if so, save from there
            var overlay = _window.FindControl<Border>("IndexFileOverlay");
            if (overlay != null && overlay.IsVisible)
            {
                var textBox = _window.FindControl<TextBox>("IndexFileTextBox");
                if (textBox != null)
                {
                    try
                    {
                        var folder = _editorState.CurrentFolder;
                        if (string.IsNullOrWhiteSpace(folder))
                        {
                            ToastService.Show("No folder open; cannot save index");
                            e.Handled = true;
                            return;
                        }

                        var indexPath = Path.Combine(folder, "_index.txt");
                        File.WriteAllText(indexPath, textBox.Text ?? string.Empty);
                        ToastService.Show("Index saved");

                        // Close overlay and reload
                        overlay.IsVisible = false;
                        _loadArticlesFromFolder?.Invoke(folder);
                    }
                    catch (Exception ex)
                    {
                        ToastService.Show("Failed to save index");
                        DebugLogger.LogException("FileKeyboardHandler: Ctrl+S save from overlay", ex);
                    }
                }
                e.Handled = true;
                return;
            }

            // Normal save (overlay not visible)
            var active = _editorState.ActiveSegment;
            if (active != null && active.IsActive)
            {
                ToastService.Show("End or cancel the active segment before saving");
                e.Handled = true;
                return;
            }

            // Save the index file directly
            var saveFolder = _editorState.CurrentFolder;
            if (string.IsNullOrWhiteSpace(saveFolder))
            {
                ToastService.Show("No folder open; cannot save index");
                e.Handled = true;
                return;
            }

            try
            {
                var links = MainWindow.Instance?.GetDiscoveredLinks();
                IndexSaver.SaveIndex(saveFolder, links);
                ToastService.Show("Index saved");
            }
            catch (Exception saveEx)
            {
                ToastService.Show("Failed to save index");
                DebugLogger.LogException("FileKeyboardHandler: Save index", saveEx);
            }
        }
        catch (Exception ex)
        {
            DebugLogger.LogException("FileKeyboardHandler: Ctrl+S handler", ex);
        }

        e.Handled = true;
    }

    private void HandleCtrlI(KeyEventArgs e)
    {
        try
        {
            var folder = _editorState.CurrentFolder;
            if (string.IsNullOrWhiteSpace(folder))
            {
                ToastService.Show("No folder open");
                e.Handled = true;
                return;
            }

            // Use OverlayManager if available, otherwise fall back to direct control access
            if (_overlayManager != null)
            {
                _overlayManager.ToggleIndexOverlay(folder);
            }
            else
            {
                // Fallback to direct control access
                var overlay = _window.FindControl<Border>("IndexFileOverlay");
                if (overlay == null)
                {
                    e.Handled = true;
                    return;
                }

                if (!overlay.IsVisible)
                {
                    var indexPath = Path.Combine(folder, "_index.txt");
                    if (!File.Exists(indexPath))
                    {
                        ToastService.Show("_index.txt not found in current folder");
                        e.Handled = true;
                        return;
                    }

                    var textBox = _window.FindControl<TextBox>("IndexFileTextBox");
                    if (textBox != null)
                    {
                        try
                        {
                            textBox.Text = File.ReadAllText(indexPath);
                        }
                        catch (Exception ex)
                        {
                            DebugLogger.LogException("FileKeyboardHandler: Read _index.txt", ex);
                            textBox.Text = "(error reading file)";
                        }
                    }

                    overlay.IsVisible = true;
                }
                else
                {
                    overlay.IsVisible = false;
                }
            }
        }
        catch (Exception ex)
        {
            DebugLogger.LogException("FileKeyboardHandler: Ctrl+I handler", ex);
        }

        e.Handled = true;
    }

    private void HandleF11(KeyEventArgs e)
    {
        _window.WindowState = _window.WindowState == Avalonia.Controls.WindowState.FullScreen 
            ? Avalonia.Controls.WindowState.Normal 
            : Avalonia.Controls.WindowState.FullScreen;
        e.Handled = true;
    }

    private void HandleCtrlB(KeyEventArgs e)
    {
        try
        {
            // Get the EditorStateViewModel from the window's DataContext
            var vm = _window.DataContext as EditorStateViewModel;
            if (vm != null)
            {
                DebugLogger.Log("FileKeyboardHandler: Ctrl+B - Checking babepedia for selected article");
                vm.CheckBabepediaForSelectedArticle();
            }
            else
            {
                DebugLogger.Log("FileKeyboardHandler: Ctrl+B - No ViewModel found");
                ToastService.Show("Cannot check babepedia - no article selected");
            }
        }
        catch (Exception ex)
        {
            DebugLogger.LogException("FileKeyboardHandler: Ctrl+B handler", ex);
        }

        e.Handled = true;
    }
}

using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

namespace IndexEditor.Services
{
    public class LinkDiscoveryService
    {
        private CancellationTokenSource? _cts;

        public event EventHandler<LinkDiscoveryProgressEventArgs>? ProgressChanged;
        public event EventHandler<LinkDiscoveredEventArgs>? LinkDiscovered;
        public event EventHandler? DiscoveryCompleted;

        public void StartDiscovery(string folder, string magazineName)
        {
            StopDiscovery();
            _cts = new CancellationTokenSource();
            Task.Run(() => DiscoverAsync(folder, magazineName, _cts.Token), _cts.Token);
        }

        public void StopDiscovery()
        {
            _cts?.Cancel();
            _cts?.Dispose();
            _cts = null;
        }

        private async Task DiscoverAsync(string folder, string magazineName, CancellationToken ct)
        {
            await Task.Yield();
            var imageFiles = IndexEditor.Shared.ImageHelper.GetAllImageFiles(folder);
            int total = imageFiles.Count;
            int processed = 0;

            foreach (var (page, path) in imageFiles)
            {
                if (ct.IsCancellationRequested) return;

                ProgressChanged?.Invoke(this, new LinkDiscoveryProgressEventArgs 
                { 
                    CurrentPage = page, 
                    TotalPages = total, 
                    ProcessedPages = processed 
                });

                try
                {
                    var text = ExtractText(path);
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        var links = FindLinks(text);
                        foreach (var (vol, num) in links)
                        {
                            if (vol > 0 && num > 0)
                            {
                                LinkDiscovered?.Invoke(this, new LinkDiscoveredEventArgs
                                {
                                    Page = page,
                                    Magazine = magazineName,
                                    Volume = vol.ToString(),
                                    Issue = num.ToString()
                                });
                            }
                        }
                    }
                }
                catch { }

                processed++;
            }

            DiscoveryCompleted?.Invoke(this, EventArgs.Empty);
        }

        private string ExtractText(string path)
        {
            try
            {
                if (!System.IO.File.Exists(path)) return string.Empty;
                var temp = System.IO.Path.GetTempFileName();
                var output = temp.Replace(".tmp", "");

                var psi = new System.Diagnostics.ProcessStartInfo
                {
                    FileName = "tesseract",
                    Arguments = $"\"{path}\" \"{output}\"",
                    UseShellExecute = false,
                    CreateNoWindow = true
                };

                using var proc = System.Diagnostics.Process.Start(psi);
                proc?.WaitForExit();

                var txtFile = output + ".txt";
                if (System.IO.File.Exists(txtFile))
                {
                    var text = System.IO.File.ReadAllText(txtFile);
                    try { System.IO.File.Delete(txtFile); } catch { }
                    try { System.IO.File.Delete(temp); } catch { }
                    return text;
                }
            }
            catch { }
            return string.Empty;
        }

        private List<(int, int)> FindLinks(string text)
        {
            var linksSet = new HashSet<(int, int)>();
            var regex = new System.Text.RegularExpressions.Regex(
                @"(vol(?:ume)?)[\s\.:/]*([0-9]+)[\s\S]*?(no(?:\.|umber)?)[\s\.:/]*([0-9]+)",
                System.Text.RegularExpressions.RegexOptions.IgnoreCase);

            foreach (System.Text.RegularExpressions.Match m in regex.Matches(text))
            {
                if (m.Success && 
                    int.TryParse(m.Groups[2].Value, out int vol) &&
                    int.TryParse(m.Groups[4].Value, out int num))
                {
                    linksSet.Add((vol, num));
                }
            }
            return new List<(int, int)>(linksSet);
        }
    }

    public class LinkDiscoveryProgressEventArgs : EventArgs
    {
        public int CurrentPage { get; set; }
        public int TotalPages { get; set; }
        public int ProcessedPages { get; set; }
        public int PercentComplete => TotalPages > 0 ? (ProcessedPages * 100) / TotalPages : 0;
    }

    public class LinkDiscoveredEventArgs : EventArgs
    {
        public int Page { get; set; }
        public string Magazine { get; set; } = string.Empty;
        public string Volume { get; set; } = string.Empty;
        public string Issue { get; set; } = string.Empty;
    }
}

using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

